fn jigsawData(puzzle: PartialInformation) PuzzleError!FullInformation {
    var result: FullInformation = undefined;

    // Initialize result fields as null (optional)
    // We'll use maybe ? types for each field, but FullInformation expects non-optional fields. So we need to fill them before returning.

    // We'll start by copying provided fields into result if not null.
    if (puzzle.pieces) |p| result.pieces = p; else result.pieces = undefined;
    if (puzzle.border) |b| result.border = b; else result.border = undefined;
    if (puzzle.inside) |i| result.inside = i; else result.inside = undefined;
    if (puzzle.rows) |r| result.rows = r; else result.rows = undefined;
    if (puzzle.columns) |c| result.columns = c; else result.columns = undefined;
    if (puzzle.aspectRatio) |ar| result.aspectRatio = ar; else result.aspectRatio = undefined;
    if (puzzle.format) |fmt| result.format = fmt; else result.format = undefined;

    // Validate consistency among provided fields.

    // 1. If format and aspectRatio both provided, check consistency.
    if (puzzle.format) |fmt| {
        if (puzzle.aspectRatio) |ar| {
            if (fmt == .square) {
                if (!std.math.approxEqAbs(f64, ar, 1.0, 1e-9)) {
                    return error.ContradictoryData;
                }
            } else if (fmt == .portrait) {
                if (ar >= 1.0) {
                    return error.ContradictoryData;
                }
            } else if (fmt == .landscape) {
                if (ar <= 1.0) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // 2. If pieces, border, inside provided, check pieces == border + inside.
    if (puzzle.pieces) |p| {
        if (puzzle.border) |b| {
            if (puzzle.inside) |i| {
                if (p != b + i) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // 3. If rows and columns provided, check pieces matches rows*columns if pieces also provided.
    if (puzzle.rows) |r| {
        if (puzzle.columns) |c| {
            if (puzzle.pieces) |p| {
                if (p != r * c) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // 4. If border provided, rows and columns must satisfy border = 2*(rows+columns)-4.
    if (puzzle.border) |b| {
        if (puzzle.rows) |r| {
            if (puzzle.columns) |c| {
                if (b != 2 * (r + c) - 4) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // 5. If inside provided, check inside = pieces - border if both pieces and border provided.
    if (puzzle.inside) |i| {
        if (puzzle.pieces) |p| {
            if (puzzle.border) |b| {
                if (i != p - b) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // 6. If aspectRatio provided, check columns/rows approx equals aspectRatio if both rows and columns known.
    if (puzzle.aspectRatio) |ar| {
        if (puzzle.rows) |r| {
            if (puzzle.columns) |c| {
                const computed = @as(f64, @intToFloat(u30, c)) / @as(f64, @intToFloat(u30, r));
                if (!std.math.approxEqAbs(f64, computed, ar, 1e-9)) {
                    return error.ContradictoryData;
                }
            }
        }
    }

    // Now we need to fill missing fields.

    // We'll attempt to derive pieces, border, inside, rows, columns, aspectRatio, format.

    // We'll use a loop to iteratively fill until all fields are known or we cannot.

    // But we can implement deterministic logic: based on which fields are known, we can compute others.

    // Let's define helper functions to compute missing fields.

    // We'll start by deriving pieces if not known but border and inside known.
    if (puzzle.pieces == null) {
        if (puzzle.border) |b| {
            if (puzzle.inside) |i| {
                result.pieces = b + i;
            }
        }
    }

    // Derive border if not known but pieces and inside known.
    if (puzzle.border == null) {
        if (puzzle.pieces) |p| {
            if (puzzle.inside) |i| {
                result.border = p - i;
            }
        }
    }

    // Derive inside if not known but pieces and border known.
    if (puzzle.inside == null) {
        if (puzzle.pieces) |p| {
            if (puzzle.border) |b| {
                result.inside = p - b;
            }
        }
    }

    // Derive rows if not known but pieces and columns known.
    if (puzzle.rows == null) {
        if (puzzle.pieces) |p| {
            if (puzzle.columns) |c| {
                if (p % c != 0) {
                    return error.ContradictoryData;
                }
                result.rows = p / c;
            }
        }
    }

    // Derive columns if not known but pieces and rows known.
    if (puzzle.columns == null) {
        if (puzzle.pieces) |p| {
            if (puzzle.rows) |r| {
